/*
b = argmin_(i ∈ ℝ) i^2 
        s.t.
        i ∈ s
        where 
        s: {ℝ} 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include <LBFGS.h>
#include <LBFGSB.h>
#include <limits>
#include <stdexcept>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT b;
    std::vector<DT > s;
    heartlib(const std::vector<DT > & s)
    {

        this->s = s;
        // b = argmin_(i ∈ ℝ) i^2 
        //         s.t.
        //         i ∈ s
            auto unpack = [&](const VectorD & X, DT & i)
            {
                i = X(0);
            };
            auto target = [&](const VectorD & X)
            {
                DT i;
                unpack(X, i);
                return DT(pow(i, 2));
            };
            VectorD best_X;
            DT best_f = std::numeric_limits<DT>::infinity();
            auto helper = [&](const VectorD & X, VectorD & grad)
            {
                VectorD Xh = X;
                for(int k = 0; k < X.size(); ++k)
                {
                    const DT h = 1e-6 * std::max(DT(1), std::abs(X(k)));
                    Xh(k) = X(k) + h;
                    const DT f_plus = target(Xh);
                    Xh(k) = X(k) - h;
                    const DT f_minus = target(Xh);
                    Xh(k) = X(k);
                    grad(k) = (f_plus - f_minus) / (2 * h);
                }
                const DT f = target(X);
                if(f < best_f){ best_f = f; best_X = X; }  // the best point evaluated, kept if the line search gives up
                return f;
            };
            VectorD lower = VectorD::Constant(1, -std::numeric_limits<DT>::infinity());
            VectorD upper = VectorD::Constant(1, std::numeric_limits<DT>::infinity());
            VectorD init = VectorD::Zero(1);
            init = init.cwiseMax(lower).cwiseMin(upper);
            DT fx;
            bool found = false;
            for(const auto & item : s)
            {
                VectorD Xs = VectorD::Constant(1, item);
                if(Xs(0) < lower(0) || Xs(0) > upper(0)) continue;
                const DT f = target(Xs);
                if(!found || f < fx){ found = true; fx = f; init = Xs; }
            }
            if(!found) throw std::runtime_error("I\u2764\uFE0FLA: no element of the set satisfies the optimization constraints");
            DT i;
            unpack(init, i);
        b = i;
    }
};

