%            s: {ℝ} 
    i = optimvar('i');
    function ret = argmin(x)
        ret = 1
        for i = 1:numel(s):
            ret *= (x[0] - s[i])
        ret = ret
    prob = optimproblem;
    {'type': 'eq', 'fun': argmin}
    prob.Objective = i.^2;
    [optimize, ~] = solve(prob);
    b = optimize.i;
    output.b = b;
    output.s = s;
end

